(()=>{'use strict';const $=id=>document.getElementById(id),M=ErrorModel,TAU=Math.PI*2;
const chapters=[
['认识误差','先有参照，才谈误差','测量误差 = 测量值 − 参考值','本例用已知参考值 50 mg P/L 的标准溶液。真实样品的真值通常未知，不能把几次测量的均值直接当成真值。'],
['两类误差','整体偏移，与逐次波动','xᵢ = μ + b + εᵢ','μ 是参考值，b 是本例恒定系统偏差，εᵢ 是每次改变的随机误差。真实系统误差也可能随时间或浓度规律变化。'],
['打靶比较','打得集中，不等于打得准','偏倚看中心，精确度看散布','靶心表示参考值；弹着中心偏离靶心反映偏倚，弹孔离散反映精确度。准确度与偏倚和精确度都有关。'],
['测量值','一次读数，拆开来看','xᵢ − μ = b + εᵢ','随机误差可以暂时抵消系统偏差，让某一次读数恰好接近参考值；不能凭一次“命中”证明方法可靠。'],
['重复与均值','增加重复，缩小均值的波动','E(x̄) = μ + b；SE = σ / √n','独立、同分布且方差有限时，重复测量可提高均值的精确度。系统偏差 b 仍然保留，n 增大不会让它消失。'],
['误差分布','一次难预测，许多次有规律','ε ~ N(0, σ²)：本例的一种模型','直方图表示模拟频率，曲线表示所选模型。切换均匀或偏态分布：随机误差不一定正态；增加样本也不会把单次误差强行变成正态。'],
['回到试验','针对来源，选择控制办法','校准查偏倚；规范操作降波动','标准物质、空白与回收试验帮助发现偏差；统一取样和测定条件改善精确度；田间采用区组、随机化和独立重复，控制环境差异。']
];
const s={step:0,bias:3,sigma:1,n:40,seed:73,distribution:'normal',shots:12,clock:0},w=new PlantWorld.World($('scene'),{yaw:-.12,pitch:.12,extent:14,target:2.7});let data=[],auto=null;const distributionCache=new Map();
function distributionValues(averages){const key=JSON.stringify([averages,s.n,s.seed,s.bias,s.sigma,s.distribution]);if(!distributionCache.has(key)){const values=averages?Array.from({length:180},(_,i)=>M.summary(M.samples({...s,seed:s.seed+i*19}).map(v=>v.value)).mean):M.samples({...s,n:800,seed:s.seed+12}).map(p=>p.epsilon);if(distributionCache.size>60)distributionCache.clear();distributionCache.set(key,values)}return distributionCache.get(key)}
document.body.classList.add('error-lab');$('stage-keyword').textContent='测量误差 · 打靶与分布';
const side=document.createElement('aside');side.className='error-panel';side.setAttribute('aria-label','误差原理与数值');document.querySelector('.stage').append(side);
function regen(){data=M.samples(s);s.shots=Math.min(s.shots,s.n);panel()}
function panel(){const c=chapters[s.step],a=data.slice(0,Math.max(2,s.shots)),q=M.summary(s.step===5?distributionValues(false):s.step===4?distributionValues(true):a.map(v=>v.value)),v=a.at(-1);side.innerHTML=`<div class="eyebrow">${String(s.step+1).padStart(2,'0')} / ${c[0]}</div><h2>${c[1]}</h2><div class="error-equation">${c[2]}</div><p>${c[3]}</p><div class="error-stats" ${[2,6].includes(s.step)?'hidden':''}><span>${s.step===4?'模拟测量组':s.step===5?'随机误差模拟':'已模拟测量'}<b>${s.step===4?180:s.step===5?800:a.length} ${s.step===4?'组':'次'}</b></span><span>${s.step===5?'随机误差均值':s.step===4?'各组均值的中心':'当前均值'} / mg P·L⁻¹<b>${q.mean.toFixed(2)}</b></span><span>${s.step===4?'组均值的经验标准差':'样本标准差 s'}<b>${q.sd.toFixed(2)}</b></span><span>${s.step===4?'理论均值标准误 σ/√n':'均值标准误估计 s/√n'}<b>${(s.step===4?M.se(s.sigma,s.n):q.se).toFixed(2)}</b></span></div>${s.step===3?`<div class="error-equation">本次 ${v.value.toFixed(2)}<br>= 50 + ${s.bias.toFixed(2)} + (${v.epsilon.toFixed(2)})</div>`:''}${s.step===4?`<div class="error-equation">σ = ${s.sigma.toFixed(2)}<br>理论 SE（n=${s.n}）= ${M.se(s.sigma,s.n).toFixed(3)}<br>期望均值 = ${(50+s.bias).toFixed(2)}</div>`:''}<p class="error-note">所有数值与弹孔均为教学模拟。金色十字是样本中心，绿色靶心是参考值。</p><details><summary>教材、术语与使用边界</summary><p>依据《植物营养研究法》“试验误差与统计基础”中真值、均值、误差分类、变异度量和随机误差分布。用打靶比喻帮助理解，不能把同一土样反复测定当成多个独立盆栽重复。</p><p>偏倚衡量系统误差；接近参考的长期中心体现正确度（trueness）。精确度描述重复结果的一致性。准确度不等同于正确度，也不是 1/s 或一个百分数。</p><p>误差不等于测量不确定度。校正偏差后仍有校准和参考值等不确定度；本例把 μ、b、σ 设为已知以便观察。</p><a href="https://jcgm.bipm.org/vim/en/2.13.html" target="_blank" rel="noopener">VIM：准确度 ↗</a> · <a href="https://jcgm.bipm.org/vim/en/2.15.html" target="_blank" rel="noopener">精确度 ↗</a><p><a href="https://github.com/Lidong-Huang/plant-nutrition-lab/blob/main/docs/误差与测量.md" target="_blank" rel="noopener">完整知识路径与模型说明 ↗</a></p></details>`;$('caption').textContent=['参照值在靶心，测量值是每一次落点。','调偏差移动整组，调 σ 改变散布。','中心接近靶心 + 弹孔集中，才是理想组合。','单次误差 = 系统偏差 + 随机误差。','重复缩小均值的随机波动，不消除偏差。','小波动较常见、大波动较少见，是正态模型的特征。','同一土样测十次 ≠ 十个独立试验重复。'][s.step];$('readout').textContent=s.step===2?'四组固定示例 · 改变偏倚与离散的组合':`参考 50 mg P/L · b=${s.bias.toFixed(1)} · σ=${s.sigma.toFixed(1)} · ${s.distribution==='normal'?'正态':s.distribution==='uniform'?'均匀':'右偏'}模拟`;$('description').textContent=c[1]+'。'+c[3];}
function ring(x,y,z,r,color){w.poly(Array.from({length:65},(_,i)=>[x+Math.cos(i/64*TAU)*r,y+Math.sin(i/64*TAU)*r,z]),color,{lit:false})}
function target(x,y,r,bias,sigma,seed,label,count=s.shots){w.box(x,y-r-1,.4,.12,1.1,.2,'#8b9d8d');w.box(x,y-r-1.05,.5,r*1.25,.08,.9,'#8e9d8a');ring(x,y,.18,r*1.04,'#6a877b');for(let i=5;i>=1;i--)ring(x,y,-.01*(6-i),r*i/5,i===1?'#2f766a':i%2?'#fcf8eb':'#c5d7c9');w.line([[x-r,y,-.075],[x+r,y,-.075]],'#a4b9a9',.65);w.line([[x,y-r,-.075],[x,y+r,-.075]],'#a4b9a9',.65);const xx=M.draws(s.n,seed,s.step===2?'normal':s.distribution),yy=M.draws(s.n,seed+137,s.step===2?'normal':s.distribution),visible=Math.min(count,s.n),pts=[];for(let i=0;i<visible;i++){const p=[x+bias*r*.23+xx[i]*sigma*r*.22,y+yy[i]*sigma*r*.22,-.11];pts.push(p);w.dot(p,r*.026,'#354c44');w.dot([p[0]+r*.008,p[1]+r*.008,-.12],r*.009,'#b5c7b2')}if(pts.length){const m=pts.reduce((a,p)=>a.map((v,i)=>v+p[i]/pts.length),[0,0,0]);w.line([[m[0]-.1,m[1],-.14],[m[0]+.1,m[1],-.14]],'#d5a44e',2);w.line([[m[0],m[1]-.1,-.14],[m[0],m[1]+.1,-.14]],'#d5a44e',2);if(!w.paused&&s.step<4){const p=pts.at(-1),f=(s.clock/.6)%1,from=[x-2,y-1,-6],q=from.map((v,i)=>v+(p[i]-v)*f);w.dot(q,.045,'#ba9b65');w.line([q,[q[0]-.18,q[1]-.05,q[2]-.22]],'#9c8b6c',1.5)}}if(label)w.label([x,y+r+.42,0],label,{size:13,pill:true})}
function axis(y=1.2){w.line([[-5.8,y,0],[5.8,y,0]],'#839c8c',1.4);for(let t=-10;t<=10;t+=5){const x=t*.5;w.line([[x,y-.08,0],[x,y+.08,0]],'#8a9e8b',1);w.label([x,y-.4,0],String(50+t),{size:11})}w.label([0,y-.8,0],'测量值 / mg P·L⁻¹',{size:11})}
function measurements(){axis();for(let i=0;i<s.shots;i++){const p=data[i],x=(p.value-50)*.5;w.dot([x,1.5+(i%10)*.22,0],.045,'#679c93')}const v=data[Math.max(0,s.shots-1)],x=(v.value-50)*.5,b=s.bias*.5;w.line([[0,1.2,-.06],[0,4.5,-.06]],'#2f7968',2);w.line([[b,1.2,0],[b,4.5,0]],'#d0a35e',1.5,{dash:[5,4]});w.line([[0,4,0],[b,4,0]],'#c09558',3);w.label([b/2,4.35,0],`b = ${s.bias.toFixed(2)}`,{size:13,pill:true});w.line([[b,3.6,-.1],[x,3.6,-.1]],'#638fac',3);w.label([(b+x)/2,3.25,-.1],`εᵢ = ${v.epsilon.toFixed(2)}`,{size:12,pill:true});w.label([0,5.1,0],`本次测得 ${v.value.toFixed(2)}，总误差 ${v.error.toFixed(2)}`,{size:17,pill:true})}
function distribution(averages=false){const values=distributionValues(averages),center=averages?50+s.bias:0,spread=averages?M.se(s.sigma,s.n):s.sigma,range=averages?Math.max(2,Math.abs(s.bias)+4*spread):Math.max(5,s.sigma*4),min=averages?50-range:-range,max=averages?50+range:range,bins=averages?100:28,h=M.histogram(values,min,max,bins),peak=Math.max(...h.map(p=>p.density),M.pdf(center,center,spread));w.line([[-5.5,.6,0],[5.5,.6,0]],'#82998b',1);for(const b of h)if(b.count>0)w.box((b.x-(averages?50:0))/range*5,.62,0,9.4/bins,b.density/peak*3.3,.65,'#a3c7bc');if(s.distribution==='normal'||averages){const curve=[];for(let i=0;i<=160;i++){const x=center-4*spread+8*spread*i/160;curve.push([(x-(averages?50:0))/range*5,.65+M.pdf(x,center,spread)/peak*3.3,-.38])}w.line(curve,'#397e75',2)}else if(s.distribution==='uniform'){const r=Math.sqrt(3)*s.sigma,y=.65+1/(2*r)/peak*3.3;w.line([[-r/range*5,.65,-.38],[-r/range*5,y,-.38],[r/range*5,y,-.38],[r/range*5,.65,-.38]],'#397e75',2)}else {const curve=[];for(let i=0;i<=140;i++){const x=-s.sigma+(max+s.sigma)*i/140;curve.push([x/range*5,.65+Math.exp(-(x/s.sigma+1))/s.sigma/peak*3.3,-.38])}w.line(curve,'#397e75',2)}const ref=averages?50:0;w.line([[0,.6,-.5],[0,4.6,-.5]],'#a88a59',1.4,{dash:[5,4]});w.label([0,.08,0],averages?'参考值 50；横轴为每组均值':'随机误差 ε；中心参考 0',{size:12,pill:true});for(let i=-2;i<=2;i++)w.label([i*2.5,.3,0],(ref+i*range/2).toFixed(1),{size:10});w.label([0,5.1,0],averages?`180 组，每组 n=${s.n}：均值仍围绕 ${(50+s.bias).toFixed(1)}`:`800 次模拟 · σ=${s.sigma.toFixed(1)} · 面积代表概率`,{size:15,pill:true});if(averages)w.label([0,4.5,0],'均值宽度 σ / √n；非正态母体时曲线仅作近似',{size:12,pill:true})}
function field(){w.ground(12,5);for(let block=0;block<3;block++)for(let t=0;t<4;t++){const x=-4.5+t*3,z=-1.5+block*1.4;w.box(x,.04,z,2.5,.15,1.05,['#c4c993','#b3bf88','#a4b67d'][block]);for(let i=0;i<5;i++){const xx=x-.9+i*.45;w.line([[xx,.2,z],[xx,.8,z]],'#688948',1.5);w.leaf([xx,.48,z],[xx-.2,.68,z+.12],.07,'#78a05c');w.leaf([xx,.6,z],[xx+.2,.83,z-.1],.07,'#86a763')}}w.label([0,2.5,0],'区组 + 随机化 + 独立重复',{size:19,pill:true});w.label([0,1.8,0],'控制位置差异，估计试验误差',{size:13,pill:true});w.label([0,-.45,2.5],'同一份土样的多次读数，只是测量重复',{size:12,pill:true})}
w.draw=()=>{if(s.step===2){target(-3.2,5.4,1.45,0,.35,73,'中心近 · 散布小');target(3.2,5.4,1.45,3,.35,73,'中心偏 · 散布小');target(-3.2,1.7,1.45,0,1.6,73,'中心近 · 散布大');target(3.2,1.7,1.45,3,1.6,73,'中心偏 · 散布大')}else if(s.step===3)measurements();else if(s.step===4)distribution(true);else if(s.step===5)distribution(false);else if(s.step===6)field();else{target(0,3,2.3,s.bias/2,s.sigma,s.seed,'参考值在靶心');w.label([0,-.25,0],s.step===0?'靶心：参考值 μ；弹孔：测量值 xᵢ':'b 让整组偏移；σ 让弹孔扩散',{size:14,pill:true})}};
function motion(){$('motion').textContent=w.paused?'▶ 动画':'Ⅱ 动画';$('motion').setAttribute('aria-pressed',String(!w.paused))}
w.update=dt=>{if(!w.paused){s.clock+=dt;if(s.clock>=.6){s.clock%=.6;if(s.shots<s.n){s.shots++;panel()}}}$('scene').dataset.step=s.step;$('scene').dataset.shots=s.shots};
function button(id,text,fn){const b=document.createElement('button');b.id=id;b.textContent=text;b.onclick=()=>{fn();panel()};$('controls').append(b);return b}
function slider(id,label,min,max,step,value,fn){const l=document.createElement('label');l.innerHTML=`${label}<input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" aria-label="${label}"><output>${value}</output>`;l.querySelector('input').oninput=e=>{const v=Number(e.target.value);l.querySelector('output').textContent=v;fn(v);regen()};$('controls').append(l)}
function controls(){$('controls').replaceChildren();if(s.step===2){[['中心近·集中',0,.35],['中心偏·集中',6,.35],['中心近·分散',0,2.5],['中心偏·分散',6,2.5]].forEach(([name,b,sigma],i)=>button('e-case-'+i,name,()=>{s.bias=b;s.sigma=sigma;regen();setStep(1)}));return}slider('e-bias','系统偏差 b',-8,8,.5,s.bias,v=>s.bias=v);slider('e-sigma','随机波动 σ',.2,4,.1,s.sigma,v=>s.sigma=v);slider('e-n','重复数 n',5,200,5,s.n,v=>s.n=v);if(s.step===5){const select=document.createElement('select');select.id='e-distribution';select.setAttribute('aria-label','随机误差分布');select.innerHTML=['normal','uniform','skew'].map((v,i)=>`<option value="${v}" ${s.distribution===v?'selected':''}>${['正态','均匀','右偏'][i]}</option>`).join('');select.onchange=()=>{s.distribution=select.value;regen()};$('controls').append(select)}button('e-repeat','重新模拟',()=>{s.seed++;s.shots=2;regen()});button('e-fire','再测一次',()=>{if(s.shots<s.n)s.shots++;else{s.seed++;s.shots=2;regen()}});if(s.step===6)button('e-calibrate','校准：将 b 归零',()=>{s.bias=0;regen();controls()})}
function stop(){clearInterval(auto);auto=null;$('play').textContent='▶';$('play').setAttribute('aria-pressed','false')}
function setStep(i){s.step=Math.max(0,Math.min(chapters.length-1,i));w.extent=s.step===2?13.5:14;w.target=s.step===2?3.3:2.7;document.querySelectorAll('#steps button').forEach((b,j)=>{b.classList.toggle('active',i===j);b.setAttribute('aria-current',i===j?'step':'false')});$('progress').textContent=(s.step+1)+' / '+chapters.length;$('prev').disabled=s.step===0;$('next').disabled=s.step===6;controls();panel()}
chapters.forEach((c,i)=>{const b=document.createElement('button');b.innerHTML=`<span>${String(i+1).padStart(2,'0')}</span>${c[0]}`;b.onclick=()=>{stop();setStep(i)};$('steps').append(b)});
$('prev').onclick=()=>{stop();setStep(s.step-1)};$('next').onclick=()=>{stop();setStep(s.step+1)};$('motion').onclick=()=>{w.paused=!w.paused;motion()};$('rotate').onclick=()=>{w.autoRotate=!w.autoRotate;$('rotate').setAttribute('aria-pressed',String(w.autoRotate))};w.onInteract=()=>$('rotate').setAttribute('aria-pressed','false');$('front').onclick=()=>{w.autoRotate=false;w.camera.yaw=0;w.camera.pitch=.05;w.camera.zoom=1};$('tilt').onclick=()=>{w.camera.pitch=w.camera.pitch>.6?.12:1.0};$('reset').onclick=()=>{stop();Object.assign(s,{bias:3,sigma:1,n:40,seed:73,distribution:'normal',shots:12,clock:0});w.resetView();regen();setStep(0)};$('play').onclick=()=>{if(auto){stop();return}w.paused=false;motion();$('play').textContent='Ⅱ';$('play').setAttribute('aria-pressed','true');auto=setInterval(()=>{if(s.step===6){stop();return}setStep(s.step+1)},10000)};$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});window.errorDiagnostics={get state(){return {...s}},get summary(){return M.summary(data.map(v=>v.value))},get samples(){return data.map(v=>({...v}))}};regen();setStep(0);motion();
})();
